# coding: utf-8
import json
from pathlib import Path
from lesson_authoring import entry as E
B=[['拉丁 debere → debitum','欠、应当 → 所欠之物']]
W=[
E('indebted','/ɪnˈdetɪd/','欠债的；感激、受恩惠的','欠别人一份：可以是钱，也可以是很难用钱计算的帮助。','从中古英语 endetten 的分词发展，往前接古法语 en- + dete“使处于债务中”；后来按拉丁来源恢复 b 的拼写，但 b 不发音。',B+[['古法语 en- + dete → endeter','使负债、进入欠债状态'],['中古英语 endetted → 英语 indebted','欠债的 → 因受帮助而感激的']],'a heavily indebted company 是负债很多的公司；I am indebted to you for your help 则是较郑重地表示“承蒙帮助，十分感激”。这里的 in- 是进入某种状态，不是否定，不能理解为“不欠债”。','be indebted to someone for；deeply indebted；heavily indebted。','in debt 更直接说欠钱；indebted to someone 常用来感谢帮助。感激义不意味着对方真的要求还钱。',('I am deeply indebted to my colleagues for their support.','我十分感激同事们给予的支持。'),('The report describes the problems facing heavily indebted companies.','报告描述了高负债企业面临的问题。'),sources=['https://www.etymonline.com/word/indebted','https://en.wiktionary.org/wiki/indebted']),
E('indebtedness','/ɪnˈdetɪdnəs/','负债状况、负债程度；感激之情','把“欠着别人”的状态作为一个整体来谈。','indebted + -ness，形容词变成表示状态的名词；debt 一支的 b 仍不发音。',B+[['英语 indebted → indebtedness','欠债、感激 → 负债状态或感激之情']],'household indebtedness 是家庭部门负债状况，level of indebtedness 看债务负担有多重；acknowledge one’s indebtedness to a teacher 则是承认自己受益于老师。后者常见于序言或致谢，语气比较郑重。','a level of indebtedness；household indebtedness；acknowledge indebtedness to。','debt 可指一笔具体债务；indebtedness 更常概括负债状态或程度。感激义也比简单的 thanks 正式。',('The study examines changes in household indebtedness.','这项研究考察了家庭负债状况的变化。'),('In the introduction, she acknowledges her indebtedness to her first teacher.','她在序言中表达了对启蒙老师的感激。'),sources=['https://en.wiktionary.org/wiki/indebtedness','https://www.etymonline.com/word/indebted']),
E('debited','/ˈdebɪtɪd/','已扣款；被记入借方','账上已经记下这一笔；银行场景常表现为钱扣走了。','debit + -ed；末尾 t 后的 -ed 读 /ɪd/，这里 b 发音，与 debt /det/ 不同。',B+[['法语 debet → 英语 debit','所欠账项 → 借方记账、扣款'],['英语 debited','过去已记账；被扣款或被记入借方']],'The fee was debited from my account 是费用从账户扣除；my account was debited 则把账户作为被动句的主语。一般会计语境中 debited 表记借方，具体增加还是减少要看账户类别，不能把所有借方都翻成“余额下降”。','be debited from an account；an account was debited；debited twice。','debit 的 b 发音，debt 和 indebted 的 b 不发音。debited 是记账动作的过去形式，不等于 debtor“欠债的人”。',('The membership fee was debited from my account yesterday.','会员费昨天已从我的账户扣除。'),('The same amount was debited twice by mistake.','同一笔金额被误扣了两次。'),sources=['https://en.wiktionary.org/wiki/debited','https://en.wiktionary.org/wiki/debit']),
E('debiting','/ˈdebɪtɪŋ/','扣款；记入借方的过程','正在把某笔金额按借方方向记到账上。','debit + -ing；重音不在最后一个音节，因此常规拼写不把末尾 t 双写。',B+[['法语 debet → 英语 debit','债务账项 → 借方记账、扣款'],['英语 debiting','正在扣款或记借方；这项操作']],'银行通知中的 debiting your account 常指从你的账户扣款。作为动作名词，debiting 可以与 crediting“记入贷方”对照。若在会计教材中看到它，要先确定是哪一类账户，不能只凭字面认为钱总是往外走。','debiting an account；before debiting；debiting and crediting。','debiting 是操作过程，a debit 是一次账项；indebted 是负债或受恩惠的状态，三者不要混用。',('The bank will notify you before debiting the annual fee.','银行会在扣取年费之前通知你。'),('The exercise asks students to practise debiting and crediting accounts.','这道练习让学生练习账户的借方和贷方记账。'),sources=['https://en.wiktionary.org/wiki/debiting','https://en.wiktionary.org/wiki/debit'])]
ROOT=dict(id='C0306',meaning='欠；应当偿还或履行',core='DEB = OWE',image='手里拿着一份还应归给别人的东西，账上便留下一笔“欠”。钱可以欠，人情也可以欠。',intro='拉丁 debere 表示欠、应当，debitum 是所欠之物。debt 和 debit 看起来几乎一样，却走过不同借入路线：前者的 b 后来补回拼写而不发音，后者读出 /b/。indebted 又把金钱上的亏欠扩展为受过帮助、心怀感激。',forms='debere 与 de- + habere“持有”有关；经过法语变化出现 dette／debt。debit 保留 b 的读音。indebted 的 in- 表进入状态，不是“不”；-ness 把它变为状态名词。debited、debiting 是 debit 的屈折形式。',branches=[['债务与债务人','debt, debtor'],['记账与扣款','debit, debited, debiting'],['负债与感激','indebted, indebtedness']],contrasts='debt /det/ 是债务，debit /ˈdebɪt/ 是借方账项或扣款动作。debtor 是欠款方，creditor 是有权收款方。借方在会计里是记账方向，并不永远表示账户减少。',practice='The fee was debited from my account. Separately, I remain deeply indebted to the friend who helped me when I was in debt.\n\n费用已经从我的账户扣除。另一方面，我仍十分感激那位曾在我欠债时帮助我的朋友。',words=['debt','debit','debtor']+[w['word'] for w in W],exclude={})
